// Helpers for scenes that are generated by a script (scenes/<id>/source/build.mjs):
// a low-poly OBJ/MTL writer with primitives, and a Standard MIDI File writer.
// Optional: scenes can just as well be modelled in Blender (File > Export > Wavefront OBJ,
// with materials) and sequenced in any MIDI editor.
import { writeFileSync, mkdirSync } from 'node:fs';
import { dirname } from 'node:path';

export function rng(seed) {
  let x = (seed >>> 0) || 1;
  return () => { x ^= x << 13; x >>>= 0; x ^= x >>> 17; x ^= x << 5; x >>>= 0; return x / 4294967296; };
}

const f3 = (n) => (Math.abs(n) < 5e-5 ? '0' : (+n.toFixed(4)).toString());
const hex = (c) => { const n = parseInt(c.slice(1), 16); return [(n >> 16 & 255) / 255, (n >> 8 & 255) / 255, (n & 255) / 255]; };

/** Low-poly mesh builder. Materials: name -> { kd: '#rrggbb' } or { ke: '#rrggbb' } (emissive). */
export class Mesh {
  constructor(materials) { this.mats = materials; this.v = []; this.faces = new Map(); this.xf = [[0, 0, 0, 0, 1]]; }
  /** push a transform [x, y, z, yaw degrees, uniform scale]; primitives use the top one */
  push(x = 0, y = 0, z = 0, yaw = 0, s = 1) { this.xf.push([x, y, z, yaw, s]); return this; }
  pop() { this.xf.pop(); return this; }
  vert(x, y, z) {
    for (let i = this.xf.length - 1; i > 0; i--) {
      const [tx, ty, tz, yaw, s] = this.xf[i], a = (yaw * Math.PI) / 180, c = Math.cos(a), sn = Math.sin(a);
      [x, y, z] = [tx + s * (x * c + z * sn), ty + s * y, tz + s * (-x * sn + z * c)];
    }
    this.v.push([x, y, z]);
    return this.v.length;   // OBJ indices are 1-based
  }
  face(mat, ...idx) {
    if (!this.mats[mat]) throw new Error('unknown material ' + mat);
    if (!this.faces.has(mat)) this.faces.set(mat, []);
    this.faces.get(mat).push(idx);
  }
  /** axis-aligned box from (x0,y0,z0) to (x1,y1,z1); skip faces with skip = 'bottom' etc. */
  box(mat, x0, y0, z0, x1, y1, z1, { skip = [] } = {}) {
    const p = [[x0, y0, z0], [x1, y0, z0], [x1, y0, z1], [x0, y0, z1], [x0, y1, z0], [x1, y1, z0], [x1, y1, z1], [x0, y1, z1]].map((q) => this.vert(...q));
    const F = { bottom: [0, 1, 2, 3], top: [4, 7, 6, 5], front: [3, 2, 6, 7], back: [1, 0, 4, 5], left: [0, 3, 7, 4], right: [2, 1, 5, 6] };
    for (const [k, q] of Object.entries(F)) if (!skip.includes(k)) this.face(mat, ...q.map((i) => p[i]));
  }
  /** quad facing +z (window strips etc.) */
  quadZ(mat, x0, y0, x1, y1, z) { this.face(mat, this.vert(x0, y0, z), this.vert(x1, y0, z), this.vert(x1, y1, z), this.vert(x0, y1, z)); }
  /** prism/frustum around the y axis: n sides, radius r0 at y0 to r1 at y1 */
  cyl(mat, n, r0, r1, y0, y1, { cx = 0, cz = 0, caps = true, rot = 0 } = {}) {
    const lo = [], hi = [];
    for (let i = 0; i < n; i++) {
      const a = rot + (i / n) * Math.PI * 2;
      lo.push(this.vert(cx + r0 * Math.cos(a), y0, cz + r0 * Math.sin(a)));
      hi.push(this.vert(cx + r1 * Math.cos(a), y1, cz + r1 * Math.sin(a)));
    }
    for (let i = 0; i < n; i++) {
      const j = (i + 1) % n;
      if (r1 > 1e-6) this.face(mat, lo[i], hi[i], hi[j], lo[j]); else this.face(mat, lo[i], hi[i], lo[j]);
    }
    if (caps && r1 > 1e-6) this.face(mat, ...hi.slice().reverse());
    if (caps) this.face(mat, ...lo);
  }
  /** low-poly dome (upper hemisphere) */
  dome(mat, n, rings, r, y0, { cx = 0, cz = 0 } = {}) {
    let prev = null;
    for (let k = 0; k <= rings; k++) {
      const phi = (k / rings) * (Math.PI / 2), rr = r * Math.cos(phi), yy = y0 + r * Math.sin(phi);
      if (k === rings) {
        const top = this.vert(cx, yy, cz);
        for (let i = 0; i < n; i++) this.face(mat, prev[i], top, prev[(i + 1) % n]);
        break;
      }
      const ring = [];
      for (let i = 0; i < n; i++) { const a = (i / n) * Math.PI * 2; ring.push(this.vert(cx + rr * Math.cos(a), yy, cz + rr * Math.sin(a))); }
      if (prev) for (let i = 0; i < n; i++) { const j = (i + 1) % n; this.face(mat, prev[i], ring[i], ring[j], prev[j]); }
      prev = ring;
    }
  }
  /** low-poly ellipsoid along x */
  ellipsoid(mat, n, rings, rx, ry, rz, { cx = 0, cy = 0, cz = 0 } = {}) {
    const rows = [];
    for (let k = 0; k <= rings; k++) {
      const th = (k / rings) * Math.PI, row = [];
      for (let i = 0; i < n; i++) {
        const a = (i / n) * Math.PI * 2;
        row.push(this.vert(cx + rx * Math.cos(th), cy + ry * Math.sin(th) * Math.cos(a), cz + rz * Math.sin(th) * Math.sin(a)));
        if (k === 0 || k === rings) break;
      }
      rows.push(row);
    }
    for (let k = 0; k < rings; k++) for (let i = 0; i < n; i++) {
      const j = (i + 1) % n, A = rows[k], B = rows[k + 1];
      if (k === 0) this.face(mat, A[0], B[i], B[j]);
      else if (k === rings - 1) this.face(mat, A[j], A[i], B[0]);
      else this.face(mat, A[i], B[i], B[j], A[j]);
    }
  }
  /** icosahedron (moon, rocks) */
  ico(mat, r, { cx = 0, cy = 0, cz = 0 } = {}) {
    const t = (1 + Math.sqrt(5)) / 2;
    const P = [[-1, t, 0], [1, t, 0], [-1, -t, 0], [1, -t, 0], [0, -1, t], [0, 1, t], [0, -1, -t], [0, 1, -t], [t, 0, -1], [t, 0, 1], [-t, 0, -1], [-t, 0, 1]]
      .map(([x, y, z]) => { const l = Math.hypot(x, y, z); return this.vert(cx + (r * x) / l, cy + (r * y) / l, cz + (r * z) / l); });
    const F = [[0, 11, 5], [0, 5, 1], [0, 1, 7], [0, 7, 10], [0, 10, 11], [1, 5, 9], [5, 11, 4], [11, 10, 2], [10, 7, 6], [7, 1, 8], [3, 9, 4], [3, 4, 2], [3, 2, 6], [3, 6, 8], [3, 8, 9], [4, 9, 5], [2, 4, 11], [6, 2, 10], [8, 6, 7], [9, 8, 1]];
    for (const [a, b, c] of F) this.face(mat, P[a], P[b], P[c]);
  }
  get triangles() { let n = 0; for (const fs of this.faces.values()) for (const f of fs) n += f.length - 2; return n; }
  write(objPath, header = '') {
    const mtlName = objPath.split('/').pop().replace(/\.obj$/, '.mtl');
    const lines = [`# ${header}`.trim(), `mtllib ${mtlName}`];
    for (const v of this.v) lines.push(`v ${f3(v[0])} ${f3(v[1])} ${f3(v[2])}`);
    for (const [m, fs] of this.faces) { lines.push(`usemtl ${m}`); for (const f of fs) lines.push('f ' + f.join(' ')); }
    const mtl = [];
    for (const [m, d] of Object.entries(this.mats)) {
      if (!this.faces.has(m)) continue;
      mtl.push(`newmtl ${m}`);
      mtl.push(`Kd ${hex(d.kd ?? d.ke).map(f3).join(' ')}`);
      if (d.ke) mtl.push(`Ke ${hex(d.ke).map(f3).join(' ')}`);
    }
    mkdirSync(dirname(objPath), { recursive: true });
    writeFileSync(objPath, lines.join('\n') + '\n');
    writeFileSync(objPath.replace(/\.obj$/, '.mtl'), mtl.join('\n') + '\n');
    return this.triangles;
  }
}

/** Standard MIDI File (format 1) writer. tracks: [{ events: [{ t (ticks), d: [bytes...] }] }] */
export function writeMidi(path, { ppq = 480, tracks }) {
  const vlq = (n) => { const b = [n & 0x7f]; while ((n >>= 7)) b.unshift((n & 0x7f) | 0x80); return b; };
  const chunk = (id, data) => [...id].map((c) => c.charCodeAt(0)).concat([data.length >>> 24, (data.length >> 16) & 255, (data.length >> 8) & 255, data.length & 255], data);
  const out = chunk('MThd', [0, 1, 0, tracks.length, ppq >> 8, ppq & 255]);
  for (const tr of tracks) {
    const ev = tr.events.map((e, i) => ({ ...e, i })).sort((a, b) => a.t - b.t || a.pri - b.pri || a.i - b.i);
    const data = [];
    let last = 0;
    for (const e of ev) { data.push(...vlq(e.t - last), ...e.d); last = e.t; }
    data.push(...vlq(0), 0xff, 0x2f, 0);
    out.push(...chunk('MTrk', data));
  }
  writeFileSync(path, Buffer.from(out));
}

/** note helper: name like "D4", "Bb3", "C#5" -> MIDI number */
export function note(n) {
  const m = /^([A-G])([b#]?)(-?\d)$/.exec(n);
  if (!m) throw new Error('bad note ' + n);
  return 12 * (+m[3] + 1) + { C: 0, D: 2, E: 4, F: 5, G: 7, A: 9, B: 11 }[m[1]] + (m[2] === '#' ? 1 : m[2] === 'b' ? -1 : 0);
}
